    /// <summary>
    /// The rating for one catalog row, picking the table the Windows row builder would have
    /// picked. Windows chooses by which builder emitted the row, not by provider, so the
    /// selection below reproduces that split from the capability instead:
    ///
    ///   BuildCloudTranscriptionRows  -> <see cref="Cloud"/>, keyed on the model id
    ///   BuildWhisperRows             -> <see cref="Whisper"/> (Windows keys on model.Type,
    ///                                   which is the same string as the portable catalog's
    ///                                   ManagedModel.Id: "base", "large-v3-turbo", ...)
    ///   BuildParakeetRows            -> <see cref="Parakeet"/>, fallback (5,3)
    ///   BuildPostProcessingRows      -> <see cref="PostProcessing"/>
    ///   BuildLocalLlmRows            -> a FLAT (3, recommended ? 4 : 3); see below
    ///   BuildCustomEndpointRows      -> a flat (3,3)
    ///
    /// The local-LLM case is the subtle one. Every gemma GGUF also has an entry in
    /// <see cref="PostProcessing"/>, but Windows does NOT use it for these rows: it hard-codes
    /// (3, recommended ? 4 : 3) at ModelLibraryManager.cs:220-221, because the GGUF's real
    /// throughput depends on the machine's GPU offload rather than on the model. Reading the
    /// PostProcessing entry here instead would show Gemma 4 E2B as 5/1 where Windows shows 3/4.
    /// </summary>
    public static ModelRating For(ModelCapability capability, ManagedModel? model = null)
    {
        ArgumentNullException.ThrowIfNull(capability);

        if (capability.Surface == ModelSurface.CustomEndpoint) return Default;

        // On-device text models are the local-LLM rows, whatever surface the catalog files
        // them under. Checked before the PostProcessing branch on purpose.
        if (capability.Deployment == ModelDeployment.Local && capability.Workload == ModelWorkload.Text)
            return new ModelRating(3, model?.IsRecommended == true ? 4 : 3);

        if (capability.Surface == ModelSurface.PostProcessing)
            return Lookup(PostProcessing, capability.ModelId, Default);

        if (capability.Deployment == ModelDeployment.Local)
        {
            // "parakeet", "parakeetLocal" and "nemotronLocal" are all the sherpa-onnx runtime;
            // the streaming rows are a second capability over the same ManagedModel.
            return capability.ProviderId.StartsWith("parakeet", StringComparison.OrdinalIgnoreCase)
                || capability.ProviderId.StartsWith("nemotron", StringComparison.OrdinalIgnoreCase)
                ? Lookup(Parakeet, capability.ModelId, ParakeetDefault)
                : Lookup(Whisper, capability.ModelId, Default);
        }

        return Lookup(Cloud, capability.ModelId, Default);
    }

    private static ModelRating Lookup(IReadOnlyDictionary<string, ModelRating> table, string id, ModelRating fallback)
        => table.TryGetValue(id, out var rating) ? rating : fallback;
}
